<?php
namespace App\Models;
use Illuminate\Foundation\Auth\User as Authenticatable; use Laravel\Sanctum\HasApiTokens; use Illuminate\Notifications\Notifiable; use Illuminate\Database\Eloquent\Factories\HasFactory;
class User extends Authenticatable { use HasApiTokens,HasFactory,Notifiable; protected $fillable=['name','email','phone','password','role','branch_id','is_active','is_online']; protected $hidden=['password','remember_token']; protected $casts=['email_verified_at'=>'datetime','password'=>'hashed','is_active'=>'boolean','is_online'=>'boolean']; public function branch(){return $this->belongsTo(Branch::class);} public function addresses(){return $this->hasMany(Address::class);} public function deviceTokens(){return $this->hasMany(DeviceToken::class);} public function orders(){return $this->hasMany(Order::class,'customer_id');} public function wallet(){return $this->hasOne(Wallet::class);} public function loyaltyAccount(){return $this->hasOne(LoyaltyAccount::class);} public function isStaff(){return $this->role!=='customer';} }